from pathlib import Path 
code = "import sqlite3\nfrom config.settings import settings\nfrom src.models.dixon_coles import calcular_probabilidades_partido\nfrom src.progol.optimizer import evaluar_valor_partido\n\ndef cargar_partidos_jornada(numero_jornada):\n    conn = sqlite3.connect(settings.DB_PATH)\n    cursor = conn.cursor()\n    query = '''SELECT p.id, e_loc.nombre as local, e_vis.nombre as visitante, m.local_xg, m.visitante_xg, pj.pct_local_publico, pj.pct_empate_publico, pj.pct_visitante_publico FROM progol_jornadas pj JOIN partidos p ON pj.partido_id = p.id JOIN equipos e_loc ON p.equipo_local_id = e_loc.id JOIN equipos e_vis ON p.equipo_visitante_id = e_vis.id JOIN metricas_avanzadas m ON p.id = m.partido_id WHERE pj.numero_jornada = ?'''\n    cursor.execute(query, (numero_jornada,))\n    filas = cursor.fetchall()\n    conn.close()\n    return filas\n\ndef generar_quiniela_optimizada(numero_jornada):\n    partidos = cargar_partidos_jornada(numero_jornada)\n    if not partidos:\n        print(f'No se encontraron partidos para la jornada {numero_jornada}.')\n        return\n    print(f'=== ANALISIS COMBINATORIO PROGOL - JORNADA {numero_jornada} ===\\n')\n    for p in partidos:\n        p_id, loc, vis, xg_l, xg_v, pct_l, pct_e, pct_v = p\n        probs = calcular_probabilidades_partido(xg_l, xg_v)\n        ev_l = evaluar_valor_partido(probs[\"prob_local\"], pct_l)\n        ev_e = evaluar_valor_partido(probs[\"prob_empate\"], pct_e)\n        ev_v = evaluar_valor_partido(probs[\"prob_visitante\"], pct_v)\n        opciones = [(\"1\", ev_l), (\"X\", ev_e), (\"2\", ev_v)]\n        opciones_ordenadas = sorted(opciones, key=lambda x: x[1], reverse=True)\n        doble_str = opciones_ordenadas[0][0] + opciones_ordenadas[1][0]\n        print(f'{loc} vs {vis}')\n        print(f'  Probabilidades -> L: {probs[\"prob_local\"]*100:.1f}%%, E: {probs[\"prob_empate\"]*100:.1f}%%, V: {probs[\"prob_visitante\"]*100:.1f}%%')\n        print(f'  Indices EV     -> L: {ev_l}, E: {ev_e}, V: {ev_v}')\n        print(f'  Sugerencia     -> Fijo: {opciones_ordenadas[0][0]} | Doble: {doble_str}')\n        print(\"-\" * 50)\n\nif __name__ == \"__main__\":\n    generar_quiniela_optimizada(2250)\n" 
